// SRP-PHAT on observed microphone spectra; no source stems or true angles.
import {FS,N,H,steering,bytes} from './array-dsp.js';
export const wrap=a=>((a+180)%360+360)%360-180;
export class Localizer {
 constructor(){this.pairs=[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]];this.lo=Math.ceil(300*N/FS);this.hi=Math.floor(4000*N/FS);this.bins=this.hi-this.lo+1;this.crossR=new Float64Array(6*this.bins);this.crossI=new Float64Array(this.crossR.length);this.templatesR=new Float64Array(72*this.crossR.length);this.templatesI=new Float64Array(this.templatesR.length);this.scores=new Float64Array(72);this.alpha=Math.exp(-H/(FS*.1));this.frame=0;this.channels=4;this.sector=180;this.anchor=0;this.direction=null;this.confidence=0;this.valid=false;this.updates=0;this.energy=0;this.age_ms=0;
 for(let a=0;a<72;a++)for(let k=this.lo;k<=this.hi;k++){let d=steering(-180+5*a,k);for(let p=0;p<6;p++){let [i,j]=this.pairs[p],r=d[i][0]*d[j][0]+d[i][1]*d[j][1],v=d[i][1]*d[j][0]-d[i][0]*d[j][1],mag=Math.hypot(r,v),q=(a*6+p)*this.bins+k-this.lo;this.templatesR[q]=r/mag;this.templatesI[q]=v/mag;}}}
 reset(){this.crossR.fill(0);this.crossI.fill(0);this.direction=null;this.confidence=0;this.valid=false;this.frame=0;this.updates=0;this.age_ms=0;}
 configure({channels,sector,anchor}={}){if(channels!==undefined&&channels!==this.channels){this.channels=channels;this.reset();}if(sector!==undefined)this.sector=sector;if(anchor!==undefined)this.anchor=wrap(anchor);}
 process(xr,xi){this.age_ms+=H/FS*1000;let energy=0;for(let k=this.lo;k<=this.hi;k++)energy+=xr[0][k]**2+xi[0][k]**2;this.energy=energy/(N*N);if(this.energy<1e-10){this.valid=false;return false;}
 for(let p=0;p<6;p++){if(this.channels===2&&p!==1)continue;let [i,j]=this.pairs[p];for(let k=this.lo;k<=this.hi;k++){let re=xr[i][k]*xr[j][k]+xi[i][k]*xi[j][k],im=xi[i][k]*xr[j][k]-xr[i][k]*xi[j][k],mag=Math.hypot(re,im),q=p*this.bins+k-this.lo;const a=1-this.alpha;this.crossR[q]=this.alpha*this.crossR[q]+a*re/Math.max(mag,1e-15);this.crossI[q]=this.alpha*this.crossI[q]+a*im/Math.max(mag,1e-15);}}
 if(++this.frame%8!==0)return false;let best=-Infinity,index=-1;for(let a=0;a<72;a++){const angle=-180+5*a;if(Math.abs(wrap(angle-this.anchor))>this.sector){this.scores[a]=NaN;continue;}let score=0;for(let p=0;p<6;p++){if(this.channels===2&&p!==1)continue;for(let k=0;k<this.bins;k++){let q=p*this.bins+k,t=a*6*this.bins+q;score+=this.crossR[q]*this.templatesR[t]+this.crossI[q]*this.templatesI[t];}}this.scores[a]=score;if(score>best){best=score;index=a;}}
 if(index<0)return false;let second=-Infinity,angle=-180+5*index;for(let a=0;a<72;a++)if(Math.abs(wrap(-180+5*a-angle))>=25&&Number.isFinite(this.scores[a]))second=Math.max(second,this.scores[a]);this.confidence=Number.isFinite(second)?Math.max(0,Math.min(1,(best-second)/Math.max(Math.abs(best),1e-9))):0;this.direction=angle;this.valid=true;this.updates++;this.age_ms=0;return true;}
 report(){return {direction_head_deg:this.direction,valid:this.valid,peak_contrast:this.confidence,channels:this.channels,updates:this.updates,age_ms:this.age_ms,grid_step_deg:5,window_ms:N/FS*1000,smoothing_time_constant_ms:100,update_interval_ms:8*H/FS*1000,sector_half_width_deg:this.sector,anchor_head_deg:this.anchor,numeric_bytes:bytes(this)};}
}
